function norm(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'');}
function keyMap(row){const out={};for(const key of Object.keys(row||{}))out[norm(key)]=key;return out;}
function get(row,aliases){const map=keyMap(row);for(const alias of aliases){const key=map[norm(alias)];if(key!==undefined)return row[key];}}
function num(value){if(value===undefined||value===null)return null;let s=String(value).trim();if(!s)return null;if(/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(s))s=s.replace(/,/g,'');else if(/^-?\d+,\d+$/.test(s))s=s.replace(',','.');const n=Number(s);return Number.isFinite(n)?n:null;}
